1	/**
2	 * The `review` use-case — the pipeline spelled out.
3	 *
4	 *   diff ─▶ impact per changed symbol ─▶ blast radius
5	 *                                          │
6	 *                     ┌────────────────────┼─────────────────────┐
7	 *                     ▼                    ▼                     ▼
8	 *              scope-creep check     test selection        radius summary
9	 *                     └────────────────────┼─────────────────────┘
10	 *                                          ▼
11	 *                                   AnalysisReport ─▶ render ─▶ publish
12	 *
13	 * Depends only on ports. The composition root supplies the implementations.
14	 */
15	import { computeBlastRadius } from "../domain/blast-radius.js";
16	import { BlastRadiusError, err, isErr, ok, type Result, settle } from "../domain/errors.js";
17	import type { AnalysisReport, RadiusNode } from "../domain/model.js";
18	import { reportBuilder } from "../domain/report.js";
19	import type { ScopeCreepStrategy } from "../domain/scope-creep/index.js";
20	import { summarizeRadius, type SummaryOptions } from "../domain/summary.js";
21	import { selectTests, type TestSelectionOptions } from "../domain/test-selection.js";
22	import type { CommitRange, GraphProvider } from "../ports/graph-provider.js";
23	import { impactQueryFor } from "../ports/graph-provider.js";
24	import type { IntentSource, PrContext } from "../ports/intent-source.js";
25	import type { ReportSink } from "../ports/report-sink.js";
26	import type { Renderer } from "../ports/renderer.js";
27	
28	export type LogLevel = "info" | "warn" | "error";
29	
30	export interface ReviewDeps {
31	  readonly graph: GraphProvider;
32	  readonly intent: IntentSource;
33	  readonly scopeCreep: ScopeCreepStrategy;
34	  /** one renderer + sink per configured output. */
35	  readonly outputs: readonly { renderer: Renderer; sink: ReportSink }[];
36	  readonly log: (level: LogLevel, message: string) => void;
37	  readonly clock?: () => Date;
38	}
39	
40	export interface ReviewRequest {
41	  readonly range: CommitRange;
42	  readonly prContext: PrContext;
43	  readonly testSelection?: TestSelectionOptions;
44	  readonly summary?: SummaryOptions;
45	}
46	
47	export interface ReviewOutcome {
48	  readonly report: AnalysisReport;
49	  readonly publishedTo: string[];
50	  /** sinks that failed — a non-fatal partial result unless every sink failed. */
51	  readonly sinkErrors: { sink: string; message: string }[];
52	  readonly hasFindings: boolean;
53	}
54	
55	export async function runReview(
56	  deps: ReviewDeps,
57	  req: ReviewRequest,
58	): Promise<Result<ReviewOutcome>> {
59	  const { graph, intent, scopeCreep, log } = deps;
60	
61	  /* 1 — changed symbols ------------------------------------------------ */
62	  const diffRes = await graph.diff(req.range);
63	  if (isErr(diffRes)) return diffRes;
64	  const changeSet = diffRes.value;
65	  log(
66	    "info",
67	    `${changeSet.symbols.length} changed symbol(s) across ${changeSet.changedFiles.length} file(s)`,
68	  );
69	
70	  /* 2 — impact per symbol -------------------------------------------- */
71	  const impactResults = await Promise.all(
72	    changeSet.symbols.map((s) => graph.impact(impactQueryFor(s.ref))),
73	  );
74	  const { values: impacts, errors: impactErrors } = settle<
75	    { nodes: readonly RadiusNode[]; disambiguationRequired: boolean },
76	    BlastRadiusError
77	  >(impactResults);
78	  for (const e of impactErrors) log("warn", `impact skipped: ${e.message}`);
79	
80	  const nodeLists = impacts.map((i) => i.nodes);
81	
82	  /* 3 — blast radius ------------------------------------------------- */
83	  const radius = computeBlastRadius(changeSet.symbols, nodeLists);
84	  log("info", `blast radius: ${radius.nodes.length} node(s)`);
85	
86	  /* 4 — intent ----------------------------------------------------- */
87	  const intentRes = await intent.get(req.prContext);
88	  const intentModel = isErr(intentRes) ? null : intentRes.value;
89	  if (isErr(intentRes)) log("warn", `intent unavailable: ${intentRes.error.message}`);
90	  else log("info", intentModel ? `intent from ${intentModel.source}` : "no stated intent found");
91	
92	  /* 5 — fan out: scope / tests / summary --------------------------- */
93	  const findings = scopeCreep.evaluate({ changeSet, intent: intentModel, radius });
94	  const testPlan = selectTests(radius, changeSet.symbols, req.testSelection);
95	  const summary = summarizeRadius(radius, req.summary);
96	
97	  /* 6 — report --------------------------------------------------- */
98	  const report = reportBuilder.build({
99	    range: { base: req.range.base, head: req.range.head, checkpoint: changeSet.checkpoint },
100	    changeSet,
101	    intent: intentModel,
102	    radius,
103	    summary,
104	    findings,
105	    testPlan,
106	    ...(deps.clock ? { now: deps.clock() } : {}),
107	  });
108	
109	  /* 7 — render + publish -------------------------------------- */
110	  const publishedTo: string[] = [];
111	  const sinkErrors: { sink: string; message: string }[] = [];
112	  for (const { renderer, sink } of deps.outputs) {
113	    const rendered = renderer.render(report);
114	    const res = await sink.publish(rendered);
115	    if (isErr(res)) {
116	      log("error", `publish to ${sink.kind} failed: ${res.error.message}`);
117	      sinkErrors.push({ sink: sink.kind, message: res.error.message });
118	      continue;
119	    }
120	    publishedTo.push(`${renderer.format}→${sink.kind}`);
121	  }
122	  // only fatal if nothing at all got out
123	  if (publishedTo.length === 0 && sinkErrors.length > 0) {
124	    return err(BlastRadiusError.sink(sinkErrors.map((e) => `${e.sink}: ${e.message}`).join("; ")));
125	  }
126	
127	  return ok({ report, publishedTo, sinkErrors, hasFindings: findings.length > 0 });
128	}

