1	/**
2	 * The human-facing PR comment.
3	 *
4	 * Layout: a badge strip, a Mermaid graph of the change and its blast radius,
5	 * the scope table (the reason this tool exists), a copy-paste test command,
6	 * then collapsed details — evidence, the test rationale, and the full node
7	 * list. Every symbol links to `file:line`; with a blob-url base it is a real
8	 * GitHub link, without one it is still a readable locator.
9	 */
10	import type { AnalysisReport } from "../../domain/model.js";
11	import type { Renderer, RenderedReport } from "../../ports/renderer.js";
12	import { COMMENT_MARKER } from "../../ports/renderer.js";
13	
14	export interface MarkdownRendererOptions {
15	  /** e.g. "https://github.com/org/repo/blob/<sha>" — makes locators clickable. */
16	  readonly repoBlobUrlBase?: string;
17	  /** total test count in the suite, for the "6 of ~N" phrasing. */
18	  readonly suiteTestCount?: number;
19	  /** tool URL for the footer. */
20	  readonly toolUrl?: string;
21	  /** draw the Mermaid diagram (default true). */
22	  readonly diagram?: boolean;
23	  /** max nodes in the diagram before it truncates (default 16). */
24	  readonly diagramMaxNodes?: number;
25	}
26	
27	const SEV_ICON = { high: "🔴", medium: "🟠", low: "🟡" } as const;
28	const SEV_COLOR = { high: "da3633", medium: "d29922", low: "bf8700" } as const;
29	
30	/** 40-hex commit SHAs render as 7 chars; refs like `main` pass through. */
31	function shortSha(ref: string): string {
32	  return /^[0-9a-f]{40}$/i.test(ref) ? ref.slice(0, 7) : ref;
33	}
34	
35	/** shields.io escaping: `-` -> `--`, `_` -> `__`, space -> `_`. */
36	function badge(label: string, message: string, color: string): string {
37	  const enc = (s: string) =>
38	    encodeURIComponent(s.replace(/-/g, "--").replace(/_/g, "__").replace(/ /g, "_"));
39	  return `![${label}](https://img.shields.io/badge/${enc(label)}-${enc(message)}-${color})`;
40	}
41	
42	export class MarkdownRenderer implements Renderer {
43	  readonly format = "markdown" as const;
44	  private readonly opts: MarkdownRendererOptions;
45	
46	  constructor(opts: MarkdownRendererOptions = {}) {
47	    this.opts = opts;
48	  }
49	
50	  render(report: AnalysisReport): RenderedReport {
51	    const out: string[] = [];
52	
53	    out.push(COMMENT_MARKER);
54	    out.push("## 🧨 Blast Radius");
55	    out.push("");
56	    out.push(this.badgeStrip(report));
57	    out.push("");
58	
59	    if (report.intent) {
60	      const title = report.intent.title || report.intent.body.slice(0, 160);
61	      out.push(`> **Intent** — _${JSON.stringify(title)}_  `);
62	      out.push(`> source: \`${report.intent.source}\`${this.checkpointNote(report)}`);
63	      out.push("");
64	    } else {
65	      out.push("> **Intent** — none found (no PR body, linked issue, or checkpoint trailer).");
66	      out.push("> Scope drift can't be judged; showing radius + tests only.");
67	      out.push("");
68	    }
69	
70	    const diagram = this.diagram(report);
71	    if (diagram) {
72	      out.push(diagram, "");
73	    }
74	
75	    /* -------- scope -------- */
76	    if (report.findings.length > 0) {
77	      out.push(`### ⚠️ Scope check — ${report.findings.length} change(s) look outside the ask`);
78	      out.push("");
79	      out.push("| | Changed symbol | Why | Dependents |");
80	      out.push("|--|--|--|--|");
81	      for (const f of report.findings) {
82	        const sym = this.locator(f.symbol.file, f.symbol.line, `\`${f.symbol.qualifiedName}\``);
83	        out.push(`| ${SEV_ICON[f.severity]} | ${sym} | ${f.reason} | ${f.dependentsCount} |`);
84	      }
85	      out.push("");
86	      out.push(this.evidenceBlock(report));
87	      out.push("");
88	    } else if (report.intent) {
89	      out.push("### ✅ Scope check — every change maps to the stated intent");
90	      out.push("");
91	    }
92	
93	    out.push(this.testsSection(report));
94	    out.push("");
95	    out.push(this.radiusSection(report));
96	    out.push("");
97	
98	    out.push("---");
99	    out.push(this.footer(report));
100	
101	    return {
102	      format: "markdown",
103	      contentType: "text/markdown",
104	      body: out.join("\n"),
105	      marker: COMMENT_MARKER,
106	    };
107	  }
108	
109	  /* ------------------------------------------------------------ sections --- */
110	
111	  private badgeStrip(r: AnalysisReport): string {
112	    const s = r.radiusSummary;
113	    const maxSev = r.findings.reduce<"high" | "medium" | "low" | null>((acc, f) => {
114	      const rank = { high: 3, medium: 2, low: 1 };
115	      return !acc || rank[f.severity] > rank[acc] ? f.severity : acc;
116	    }, null);
117	
118	    const badges = [
119	      badge("blast radius", `${s.totalNodes} nodes`, "1f6feb"),
120	      badge("modules", String(s.moduleCount), "1f6feb"),
121	    ];
122	    if (s.serviceCount > 0) badges.push(badge("services", String(s.serviceCount), "8250df"));
123	    badges.push(
124	      r.findings.length === 0
125	        ? badge("scope", "clean", "2da44e")
126	        : badge("scope", `${r.findings.length} findings`, maxSev ? SEV_COLOR[maxSev] : "d29922"),
127	    );
128	    const gaps = r.testPlan.coverageGaps.length;
129	    badges.push(
130	      gaps > 0
131	        ? badge("tests", `${r.testPlan.selected.length} · ${gaps} gaps`, "bf8700")
132	        : badge("tests", `${r.testPlan.selected.length} selected`, "2da44e"),
133	    );
134	    badges.push(
135	      badge("intent", r.intent ? r.intent.source : "none", r.intent ? "8250df" : "8b949e"),
136	    );
137	    return badges.join(" ");
138	  }
139	
140	  /**
141	   * A Mermaid flowchart: changed symbols in the centre (red = flagged, amber =
142	   * clean), with the callers that reach them fanned out to the left. This is
143	   * the graph the whole tool runs on, shown directly.
144	   */
145	  private diagram(r: AnalysisReport): string | null {
146	    if (this.opts.diagram === false) return null;
147	    const cap = this.opts.diagramMaxNodes ?? 16;
148	
149	    const changed = r.changedSymbols.filter(
150	      (c) =>
151	        c.changeType !== "added" ||
152	        r.radiusNodes.some((n) => n.origins.includes(c.ref.qualifiedName)),
153	    );
154	    if (changed.length === 0) return null;
155	
156	    const callers = r.radiusNodes
157	      .filter((n) => n.section === "callers")
158	      .sort((a, b) => a.distance - b.distance);
159	    if (callers.length === 0) return null;
160	
161	    const id = mermaidIds();
162	    const lines: string[] = ["```mermaid", "flowchart LR"];
163	    let count = 0;
164	
165	    for (const c of changed) {
166	      if (count >= cap) break;
167	      const cls = c.isFinding ? "finding" : "changed";
168	      lines.push(
169	        `  ${id.for(c.ref.qualifiedName)}["${mermaidLabel(c.ref.qualifiedName)}"]:::${cls}`,
170	      );
171	      count++;
172	    }
173	
174	    const shownCallers = new Set<string>();
175	    for (const n of callers) {
176	      if (count >= cap) {
177	        lines.push(`  more["+ ${callers.length - shownCallers.size} more callers…"]:::more`);
178	        break;
179	      }
180	      const key = n.ref.qualifiedName;
181	      if (shownCallers.has(key)) continue;
182	      shownCallers.add(key);
183	      const target =
184	        n.via.length > 0 && id.has(n.via[n.via.length - 1]!)
185	          ? n.via[n.via.length - 1]!
186	          : n.origins[0];
187	      if (!target || !id.has(target)) continue;
188	      if (!id.has(key)) {
189	        const cls = n.isTest ? "test" : "caller";
190	        lines.push(`  ${id.for(key)}["${mermaidLabel(key)}"]:::${cls}`);
191	        count++;
192	      }
193	      lines.push(`  ${id.for(key)} --> ${id.for(target)}`);
194	    }
195	
196	    lines.push(
197	      "  classDef finding fill:#ffdcdc,stroke:#e5534b,color:#86181d;",
198	      "  classDef changed fill:#fff3d4,stroke:#d4a72c,color:#7a5c00;",
199	      "  classDef caller fill:#eef2f6,stroke:#8c959f,color:#1f2328;",
200	      "  classDef test fill:#e6f4ea,stroke:#4c9a5f,color:#1a4d2e;",
201	      "  classDef more fill:#f6f8fa,stroke:#d0d7de,color:#57606a;",
202	      "```",
203	    );
204	    return lines.join("\n");
205	  }
206	

