140	  /**
141	   * A Mermaid flowchart: changed symbols in the centre (red = flagged, amber =
142	   * clean), with the callers that reach them fanned out to the left. This is
143	   * the graph the whole tool runs on, shown directly.
144	   */
145	  private diagram(r: AnalysisReport): string | null {
146	    if (this.opts.diagram === false) return null;
147	    const cap = this.opts.diagramMaxNodes ?? 16;
148	
149	    const changedNames = new Set(r.changedSymbols.map((c) => c.ref.qualifiedName));
150	    const changed = r.changedSymbols.filter((c) => {
151	      // a new symbol only earns a node if something in the radius points at it
152	      if (
153	        c.changeType === "added" &&
154	        !r.radiusNodes.some((n) => n.origins.includes(c.ref.qualifiedName))
155	      ) {
156	        return false;
157	      }
158	      // drop a container (class/interface) if one of its own members also changed
159	      // — the member node says everything the container would, without the island
160	      const isContainer = c.ref.kind === "class" || c.ref.kind === "interface";
161	      if (isContainer) {
162	        const prefix = `${c.ref.qualifiedName}.`;
163	        if ([...changedNames].some((n) => n.startsWith(prefix))) return false;
164	      }
165	      return true;
166	    });
167	    if (changed.length === 0) return null;
168	
169	    const callers = r.radiusNodes
170	      .filter((n) => n.section === "callers")
171	      .sort((a, b) => a.distance - b.distance);
172	    if (callers.length === 0) return null;
173	
174	    const id = mermaidIds();
175	    const lines: string[] = ["```mermaid", "flowchart LR"];
176	    let count = 0;
177	
178	    for (const c of changed) {
179	      if (count >= cap) break;
180	      const cls = c.isFinding ? "finding" : "changed";
181	      lines.push(
182	        `  ${id.for(c.ref.qualifiedName)}["${mermaidLabel(c.ref.qualifiedName)}"]:::${cls}`,
183	      );
184	      count++;
185	    }
186	
187	    // call edges among the changed symbols themselves
188	    for (const e of r.originEdges) {
189	      if (id.has(e.from) && id.has(e.to)) {
190	        lines.push(`  ${id.for(e.from)} --> ${id.for(e.to)}`);
191	      }
192	    }
193	
194	    const shownCallers = new Set<string>();
195	    for (const n of callers) {
196	      if (count >= cap) {
197	        lines.push(`  more["+ ${callers.length - shownCallers.size} more callers…"]:::more`);
198	        break;
199	      }
200	      const key = n.ref.qualifiedName;
201	      if (shownCallers.has(key)) continue;
202	      shownCallers.add(key);
203	      const target =
204	        n.via.length > 0 && id.has(n.via[n.via.length - 1]!)
205	          ? n.via[n.via.length - 1]!
206	          : n.origins[0];
207	      if (!target || !id.has(target)) continue;
208	      if (!id.has(key)) {
209	        const cls = n.isTest ? "test" : "caller";
210	        lines.push(`  ${id.for(key)}["${mermaidLabel(key)}"]:::${cls}`);
211	        count++;
212	      }
213	      lines.push(`  ${id.for(key)} --> ${id.for(target)}`);
214	    }
215	
